const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let trashUi=null,propertyInspector=null,pdfThumbnails=null;
let key='',libraryId='',items=[],folders=[],view='all',folderId='',tag='',selecting=false,selection=new Set(),visible=[],current=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bytes=n=>n>=1048576?(n/1048576).toFixed(2)+' MB':Math.ceil(n/1024)+' KB';
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
async function api(route,options={}){const r=await fetch('/api/'+route,{...options,headers:{'X-Assetnest-Key':key,...(libraryId?{'X-Assetnest-Library':libraryId}:{}),...options.headers}});if(!r.ok){let data;try{data=await r.json();}catch{}throw Error(data?.error||'请求失败');}return r;}
const post=(route,p,method='POST')=>api(route,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(p)}).then(r=>r.json());
const wrap=fn=>async(...args)=>{try{await fn(...args);}catch(e){toast(e.message);console.error(e);}};
const nativeDesktop=window.assetnestDesktop?.host==='webview2';document.body.classList.toggle('native-desktop',nativeDesktop);
function folderPath(f){const names=[f.name],seen=new Set([f.id]);let p=folders.find(c=>c.id===f.parentId);while(p&&!seen.has(p.id)){seen.add(p.id);names.unshift(p.name);p=folders.find(c=>c.id===p.parentId);}return names.join(' / ');}
function folderOptions(value=''){return '<option value="">未分类</option>'+folders.map(f=>`<option value="${esc(f.id)}" ${f.id===value?'selected':''}>${esc(folderPath(f))}</option>`).join('');}
function updateNavigationState(){for(const button of $$('#navigation .nav')){const active=!activeSmart&&!folderId&&!tag&&(quickView?button.dataset.quick===quickView:button.dataset.view===view);button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');}}
async function assignToFolder(ids,target,expectedLibrary=libraryId){if(expectedLibrary!==libraryId)throw Error('素材库已切换，请重新拖动');await post('batch-edit',{ids,folderMode:'add',folders:[target]});selection.clear();selecting=false;anchorId=null;await refresh();toast('已将 '+ids.length+' 个素材添加到“'+(folders.find(f=>f.id===target)?.name||'文件夹')+'”');}
function setView(v,f='',t=''){leavePreview();quickView=null;inspectedId=null;view=v;folderId=f;tag=t;activeSmart=null;selection.clear();selecting=false;anchorId=null;updateNavigationState();requestSearch();}
function render(){
 visible=items.slice();trashUi?.update({view,selection,total:facets.trash??pageInfo.total});
 const title=quickView?({unclassified:'未分类',untagged:'未标签',random:'随机模式',captured:'采集定位'})[quickView]:activeSmart?'智能 · '+activeSmart.name:folderId?folders.find(f=>f.id===folderId)?.name:tag?'# '+tag:({all:'全部素材',recent:'最近添加',star:'星标收藏',trash:'回收站'})[view];
 $('#breadcrumb').textContent=title;$('#page-title').firstChild.textContent=title;$('#heading-count').textContent=pageInfo.total;$('#total-count').textContent=facets.total;
 $('#page-description').textContent=view==='trash'?'暂时收起的灵感，随时可以恢复。':view==='recent'?'过去七天收集的新灵感。':'收集灵感，让每个好想法都有迹可循。';
 updateNavigationState();
 renderFolderTree();
 const tags=(facets.tags||[]).map(t=>t.name);$('#tag-list').innerHTML=tags.length?tags.slice(0,40).map(t=>`<button data-tag="${esc(t)}" class="${tag===t?'active':''}"># ${esc(t)}</button>`).join(''):'<small style="color:#b0b4bf;font-size:11px">为素材添加标签后显示</small>';
 $('#grid').innerHTML=visible.map(i=>`<article class="card ${selection.has(i.id)?'selected':''}" data-id="${esc(i.id)}" tabindex="0" draggable="true" role="button" aria-label="${esc(i.name)}"><div class="card-image"><img draggable="false" src="${i.ext.toLowerCase()==='url'&&!i.hasThumbnail?'/bookmark.svg':'/media/'+esc(i.id)+'/thumb'}" alt="${esc(i.name)}" loading="lazy"><span class="ext">${esc(i.ext.toUpperCase())}</span><button class="star ${i.star?'saved':''}" data-star="${esc(i.id)}" aria-label="星标收藏">${i.star?'★':'☆'}</button></div><div class="card-info"><div class="card-title" title="${esc(i.name)}">${esc(i.name.toLowerCase().endsWith('.'+i.ext.toLowerCase())?i.name:i.name+'.'+i.ext)}</div><div class="card-meta"><span>${i.width&&i.height?i.width+' × '+i.height:esc(i.ext.toUpperCase())}</span><span>${bytes(i.size)}</span></div>${i.tags?.length?`<div class="card-tags">${i.tags.map(t=>'# '+esc(t)).join('　')}</div>`:''}</div></article>`).join('');
 $('#empty').hidden=visible.length>0;$('#footer-count').textContent=`本页 ${visible.length} / ${pageInfo.total} 个素材 · ${bytes(visible.reduce((a,i)=>a+i.size,0))}`;$('#selection-bar').hidden=!selecting;$('#selection-count').textContent=`已选择 ${selection.size} 个素材（当前页选择）`;$('#selection-trash').textContent=view==='trash'?'恢复所选':'移到回收站';updateInspector();layoutReferenceGrid();pdfThumbnails?.observe(visible);
}
async function refresh(){facets=await(await api('facets')).json();folders=facets.folders;const selectedBatch=batchFilter.value;batchFilter.innerHTML='<option value="">全部导入来源</option><option value="__local">本地 / 旧版素材</option>'+(facets.sources||[]).map(s=>`<option value="${esc(s.id)}">批次 ${esc(s.id.slice(-8))}</option>`).join('');batchFilter.value=selectedBatch;renderSmartFolders();await loadPage();}

function openAdd(){$('#add-form .folder-select').innerHTML=folderOptions(folderId);$('#add-dialog').showModal();}
function detail(id){current=items.find(i=>i.id===id);if(!current)return;const i=current,f=$('#detail-form');f.elements.name.value=i.name;f.elements.tags.value=(i.tags||[]).join(', ');f.elements.annotation.value=i.annotation||'';f.elements.folderId.innerHTML=folderOptions();for(const o of f.elements.folderId.options)o.selected=(i.folders||[]).includes(o.value);f.elements.star.value=i.star||0;resetZoom();$('#detail-image').src=i.ext.toLowerCase()==='url'?(i.hasThumbnail?'/media/'+i.id+'/thumb':'/bookmark.svg'):'/media/'+i.id+(['tif','tiff','psd'].includes(i.ext.toLowerCase())?'/preview':'/original');$('#detail-image').alt=i.name;$('#detail-stats').textContent=[i.ext.toUpperCase(),i.width&&i.height?i.width+' × '+i.height:'',bytes(i.size),new Date(i.modificationTime).toLocaleDateString('zh-CN')].filter(Boolean).join(' · ');const a=$('#detail-source');a.textContent=i.url||'未记录来源';if(/^https?:\/\//i.test(i.url||''))a.href=i.url;else a.removeAttribute('href');$('#original-link').href=i.ext.toLowerCase()==='url'&&/^https?:\/\//i.test(i.url||'')?i.url:'/media/'+i.id+'/original';$('#original-link').textContent=i.ext.toLowerCase()==='url'?'打开网页 ↗':'查看原图 ↗';$('#detail-star').textContent=i.star?'★':'☆';$('#detail-trash').textContent=i.isDeleted?'恢复素材':'移到回收站';$('#palette').replaceChildren();for(const p of (i.palettes?.length?i.palettes:(i.extractedPalette||[])).slice(0,8)){if(!Array.isArray(p.color)||p.color.length!==3)continue;const s=document.createElement('span');s.style.background=`rgb(${p.color.map(n=>Math.max(0,Math.min(255,Number(n)||0))).join(',')})`;s.title=p.color.join(', ');$('#palette').append(s);}showPreviewShell(i);propertyInspector?.render(i,folders,facets.tags||[]);pdfThumbnails?.request(i);if(!$('#detail-dialog').open)$('#detail-dialog').show();void openViewer(i,{saveRegions:async(id,regions)=>{await post('items/'+id,{assetnestRegions:regions},'PATCH');const entry=items.find(x=>x.id===id);if(entry)entry.assetnestRegions=regions;},onError:toast});}
async function exportSelected(ids){const job=await post('jobs/export',{ids});toast('已开始导出，可在“任务与维护”查看进度或取消');await openMaintenance();void trackExport(job.id);}
async function trackExport(id){try{for(;;){const job=await(await api('jobs/'+id)).json();if(job.status==='completed'){const a=document.createElement('a');a.href=job.download;a.download='拾素材-'+new Date().toISOString().slice(0,10)+'.eaglepack';a.click();toast('素材包已生成，开始下载');if($('#maintenance-dialog').open)await updateMaintenance();break;}if(job.status!=='running'){toast(job.status==='cancelled'?'导出已取消':'导出失败：'+job.error);break;}await new Promise(r=>setTimeout(r,750));}}catch(e){toast(e.message);}}
let importPending=null,lastReport=null;
function showReport(title,report){lastReport=report;$('#report-title').textContent=title;$('#report-content').textContent=JSON.stringify(report,null,2);$('#report-dialog').showModal();}
function confirmImport(preview){const r=preview.report;$('#import-summary').textContent=`共 ${r.total} 项 · 新增 ${r.imported} · 不变 ${r.duplicates} · 素材冲突 ${r.conflicts} · 文件夹冲突 ${r.folderConflicts}。预计暂存需 ${bytes(r.space.requiredBytes)}。`;$('#import-preview-report').textContent=JSON.stringify(r,null,2);$('#import-dialog').showModal();return new Promise((resolve,reject)=>importPending={token:preview.token,resolve,reject});}
async function cancelImport(){const pending=importPending;importPending=null;if(pending){try{await post('import-cancel',{token:pending.token});}finally{pending.resolve(null);}}$('#import-dialog').close();}
$('#import-cancel').onclick=wrap(cancelImport);$('#import-cancel-bottom').onclick=wrap(cancelImport);$('#import-dialog').addEventListener('cancel',e=>{e.preventDefault();wrap(cancelImport)();});
$('#import-confirm').onclick=wrap(async()=>{const pending=importPending;if(!pending)return;$('#import-confirm').disabled=true;try{const report=await post('import-confirm',{token:pending.token});importPending=null;$('#import-dialog').close();pending.resolve(report);}catch(e){importPending=null;$('#import-dialog').close();pending.reject(e);}finally{$('#import-confirm').disabled=false;}});
$('#download-report').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(lastReport,null,2)],{type:'application/json'}));a.href=url;a.download='assetnest-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);};
async function importFiles(files){let imported=0,duplicate=0,lastImport=null;for(const file of files){toast('正在检查 '+file.name+'…');if(file.name.toLowerCase().endsWith('.eaglepack')){const preview=await(await api('import-preview',{method:'POST',body:file})).json();const j=await confirmImport(preview);if(!j)continue;imported+=j.imported;duplicate+=j.duplicates;lastImport=j;}else {const j=await(await api('upload',{method:'POST',headers:{'X-File-Name':encodeURIComponent(file.name)},body:file})).json();j.duplicate?duplicate++:imported++;}}await refresh();toast(`处理完成：新增 ${imported} 个素材${duplicate?'，跳过 '+duplicate+' 个不变项':''}`);if(lastImport)showReport('素材包导入报告',lastImport);}
$('#navigation').onclick=e=>{const b=e.target.closest('[data-view]');if(b)setView(b.dataset.view);};$('#folder-list').onclick=e=>{const b=e.target.closest('[data-folder]');if(b)setView('all',b.dataset.folder);};$('#tag-list').onclick=e=>{const b=e.target.closest('[data-tag]');if(b)setView('all','',b.dataset.tag);};
for(const s of ['#search','#type-filter','#sort'])$(s).addEventListener(s==='#search'?'input':'change',requestSearch);
$('#grid').onclick=wrap(async e=>{const star=e.target.closest('[data-star]');if(star){const i=items.find(i=>i.id===star.dataset.star);await post('items/'+i.id,{star:i.star?0:1},'PATCH');await refresh();return;}const c=e.target.closest('[data-id]');if(!c)return;if(selecting){selection.has(c.dataset.id)?selection.delete(c.dataset.id):selection.add(c.dataset.id);render();}else detail(c.dataset.id);});
$('#grid').onkeydown=e=>{if(e.key==='Enter')e.target.closest('[data-id]')?.click();};
$('#refresh-button').onclick=wrap(refresh);$('#grid-button').onclick=()=>{$('#grid').classList.remove('list');$('#grid-button').classList.add('selected');$('#list-button').classList.remove('selected');};$('#list-button').onclick=()=>{$('#grid').classList.add('list');$('#list-button').classList.add('selected');$('#grid-button').classList.remove('selected');};
$('#capture-button').onclick=openAdd;$('#empty-import').onclick=()=>$('#file-picker').click();$('#import-button').onclick=()=>{$('#file-picker').accept='.eaglepack';$('#file-picker').click();};$('#upload-button').onclick=()=>{$('#file-picker').accept='*/*';$('#file-picker').click();};$('#file-picker').onchange=wrap(async e=>{try{await importFiles(e.target.files);}finally{e.target.value='';}});
$('#add-form').onsubmit=wrap(async e=>{e.preventDefault();const f=e.target,p=Object.fromEntries(new FormData(f));if(!p.url)throw Error('请输入图片直链');p.tags=p.tags.split(/[,，]/).map(s=>s.trim()).filter(Boolean);const b=f.querySelector('[type=submit]');b.disabled=true;try{const r=await post('capture',p);await refresh();$('#add-dialog').close();f.reset();toast(r.duplicate?'图片已在素材库中':'图片已收入素材库');}finally{b.disabled=false;}});
$('#new-folder').onclick=wrap(async()=>{const name=prompt('文件夹名称');if(name?.trim()){await post('folders',{name});await refresh();}});
$('#detail-form').onsubmit=wrap(async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));p.tags=p.tags.split(/[,，]/).map(s=>s.trim()).filter(Boolean);p.folders=[...e.target.elements.folderId.selectedOptions].map(o=>o.value).filter(Boolean);p.star=Number(p.star);delete p.folderId;await post('items/'+current.id,p,'PATCH');const savedId=current.id;await refresh();if(items.some(i=>i.id===savedId))detail(savedId);else{leavePreview();inspectedId=null;updateInspector();}toast('已保存');});
$('#detail-star').onclick=wrap(async()=>{const id=current.id;await post('items/'+id,{star:current.star?0:1},'PATCH');await refresh();detail(id);});$('#detail-trash').onclick=wrap(async()=>{await post('items/'+current.id,{isDeleted:!current.isDeleted},'PATCH');await refresh();$('#detail-dialog').close();toast('已更新素材');});$('#detail-close').onclick=()=>$('#detail-dialog').close();for(const [s,delta]of [['#previous-item',-1],['#next-item',1]])$(s).onclick=()=>{void navigatePreview(delta);};
$('#select-button').onclick=()=>{selecting=!selecting;selection.clear();render();};$('#selection-cancel').onclick=()=>{selecting=false;selection.clear();render();};$('#export-button').onclick=wrap(async()=>{const result=await post('search',{...searchRequest(),idsOnly:true});await exportSelected(result.ids);});$('#selection-export').onclick=wrap(()=>{if(!selection.size)throw Error('请先选择素材');return exportSelected([...selection]);});$('#selection-trash').onclick=wrap(async()=>{await post('batch-edit',{ids:[...selection],patch:{isDeleted:view!=='trash'}});selection.clear();await refresh();toast('所选素材已更新');});
$('#settings-button').onclick=()=>$('#settings-dialog').showModal();$('#copy-key').onclick=wrap(async()=>{await navigator.clipboard.writeText(key);toast('已复制连接密钥');});$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d&&e.offsetX<0)d.close();}));
$('#copy-extension-path').onclick=wrap(async()=>{await navigator.clipboard.writeText($('#extension-path').textContent);toast('已复制插件目录');});
$('#download-extension').onclick=wrap(async()=>{const r=await api('extension-download');const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=r.headers.get('Content-Disposition')?.match(/filename=([^;]+)/)?.[1]||'assetnest-extension.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('插件 ZIP 已下载，解压后加载到浏览器');});
const tools=document.createElement('div');tools.className='dialog-actions';tools.innerHTML='<button id="integrity-check">完整性检查</button><button id="create-backup">创建备份</button><button id="import-history">导入记录</button>';$('#settings-dialog').append(tools);
const maintenanceButton=document.createElement('button');maintenanceButton.id='open-maintenance';maintenanceButton.textContent='任务与维护';tools.prepend(maintenanceButton);maintenanceButton.onclick=wrap(openMaintenance);
const maintenanceDialog=document.createElement('dialog');maintenanceDialog.id='maintenance-dialog';maintenanceDialog.innerHTML='<div style="min-width:min(600px,75vw);max-width:80vw"><div class="dialog-header"><h2>任务与维护</h2><button id="maintenance-close">关闭</button></div><p id="maintenance-summary" class="muted"></p><div id="maintenance-jobs"></div><div class="dialog-actions"><button id="maintenance-refresh">刷新状态</button><button id="maintenance-cache">清理预览缓存</button></div><p class="muted">预览缓存会按需重新生成。已完成的素材包保留 10 分钟，预检文件保留 5 分钟。导出及后台维护期间仍可浏览，修改、采集和切换素材库需等待或取消任务。</p></div>';document.body.append(maintenanceDialog);
const thumbnailTasks=installPreviewTasks({api,post,toast});
const backgroundMaintenance=installMaintenanceUi({api,post,toast,showReport,openMaintenance});
const watchFoldersUi=installWatchFolders({api,post,toast});
let maintenanceTimer;
async function openMaintenance(){if(!maintenanceDialog.open)maintenanceDialog.showModal();await updateMaintenance();clearInterval(maintenanceTimer);maintenanceTimer=setInterval(()=>{if(maintenanceDialog.open)void updateMaintenance().catch(e=>toast(e.message));},1500);}
async function updateMaintenance(){await watchFoldersUi.update();await thumbnailTasks.update();const t=await(await api('jobs')).json();backgroundMaintenance.render(t);const d=await(await api('diagnostics')).json();$('#maintenance-summary').textContent=`${d.library} · ${d.items} 项 · 可用空间 ${bytes(d.freeBytes)} · 预览缓存 ${bytes(d.cacheBytes)} · 索引 ${d.indexed}/${d.items} · ${d.sqlite.every(r=>Object.values(r).includes('ok'))?'数据库检查通过':'请执行完整性检查'}`;const labels={running:'正在导出',completed:'已完成',failed:'失败',cancelled:'已取消'};$('#maintenance-jobs').innerHTML=t.jobs.some(j=>j.type==='export')?t.jobs.filter(j=>j.type==='export').map(j=>`<div style="padding:12px 0;border-bottom:1px solid #444"><strong>${labels[j.status]||esc(j.status)}</strong> · ${j.completed}/${j.entries} 个文件 · ${bytes(j.bytes)}${j.error?'<p>'+esc(j.error)+'</p>':''} ${j.download?`<a href="${esc(j.download)}" download>下载素材包</a>`:''}${j.status==='running'?`<button data-cancel-job="${esc(j.id)}">取消任务</button>`:''}</div>`).join(''):'<p class="muted">暂无素材包任务</p>';$$('[data-cancel-job]').forEach(b=>b.onclick=wrap(async()=>{await post('jobs/'+b.dataset.cancelJob+'/cancel',{});await updateMaintenance();}));}
$('#maintenance-close').onclick=()=>maintenanceDialog.close();maintenanceDialog.addEventListener('close',()=>clearInterval(maintenanceTimer));$('#maintenance-refresh').onclick=wrap(updateMaintenance);$('#maintenance-cache').onclick=wrap(async()=>{const result=await post('cache/clear',{});toast('已清理 '+bytes(result.bytes)+' 预览缓存；后台队列已暂停，可点击继续生成');await updateMaintenance();});
$('#integrity-check').onclick=wrap(()=>backgroundMaintenance.start('integrity'));
$('#create-backup').onclick=wrap(()=>backgroundMaintenance.start('backup'));
$('#import-history').onclick=wrap(async()=>showReport('最近导入记录',await(await api('import-reports')).json()));
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$$('dialog').some(d=>d.open)){e.preventDefault();$('#search').focus();}});
let dragCounter=0;document.addEventListener('dragenter',e=>{if([...e.dataTransfer.types].includes('Files')){e.preventDefault();dragCounter++;$('#drop-overlay').hidden=false;}});document.addEventListener('dragleave',()=>{if(--dragCounter<=0){$('#drop-overlay').hidden=true;dragCounter=0;}});document.addEventListener('dragover',e=>e.preventDefault());document.addEventListener('drop',wrap(async e=>{e.preventDefault();dragCounter=0;$('#drop-overlay').hidden=true;await importFiles(e.dataTransfer.files);}));
const batchFilter=document.createElement('select');batchFilter.id='batch-filter';batchFilter.title='按导入来源筛选后可保留各素材包根数据分别导出';batchFilter.innerHTML='<option value="">全部导入来源</option>';$('#type-filter').before(batchFilter);batchFilter.onchange=requestSearch;
// Organization controls share the existing catalog and transaction APIs.
const collapsedFolders=new Set();let anchorId=null,zoom=1,panX=0,panY=0,panStart=null;
function sortedFolders(parent=null){return folders.filter(f=>(f.parentId||null)===parent).sort((a,b)=>(a.order||0)-(b.order||0));}
function folderIconMarkup(folder){const icon=folderIcons.includes(folder.icon)?folder.icon:'folder',color=folderColors[folder.iconColor]||folderColors[''];return '<span class="folder-symbol" aria-hidden="true" style="--folder-icon:url(/vendor/folder-icons/'+icon+'.svg);color:'+color+'"></span>';}
function renderFolderTree(){
 const seen=new Set();function branch(parent,depth){return sortedFolders(parent).map(f=>{if(seen.has(f.id))return '';seen.add(f.id);const hasChild=folders.some(c=>c.parentId===f.id),collapsed=collapsedFolders.has(f.id);return `<div class="folder-row ${folderId===f.id?'active':''}" data-folder-row="${esc(f.id)}" style="--folder-depth:${depth}"><button class="folder-toggle" data-toggle="${esc(f.id)}" aria-label="展开或折叠" ${hasChild?'aria-expanded="'+!collapsed+'"':'disabled tabindex="-1"'}>${hasChild?(collapsed?'▸':'▾'):''}</button><button class="folder ${folderId===f.id?'active':''}" data-folder="${esc(f.id)}" title="${esc(f.name)}">${folderIconMarkup(f)}<span class="folder-name">${esc(f.name)}</span><small aria-label="${f.count||0} 个素材">${f.count||''}</small></button><button class="folder-edit" data-edit-folder="${esc(f.id)}" aria-label="编辑文件夹">⋯</button></div>${collapsed?'':branch(f.id,depth+1)}`;}).join('');}$('#folder-list').innerHTML=branch(null,0);
}
