function layoutReferenceGrid(){const grid=$('#grid');if(!grid||!$('#density'))return;const target=Number($('#density').value),columns=Math.max(1,Math.floor((grid.clientWidth+8)/(target+8))),cards=[...grid.children];for(let offset=0;offset<cards.length;offset+=columns){const row=cards.slice(offset,offset+columns),ratios=row.map(card=>{const img=card.querySelector('img'),item=visible.find(i=>i.id===card.dataset.id);if(img&&!img.complete&&!img.dataset.layout){img.dataset.layout='1';img.addEventListener('load',layoutReferenceGrid,{once:true});}return Math.max(.4,Math.min(1.6,img?.naturalWidth&&img?.naturalHeight?img.naturalWidth/img.naturalHeight:item?.width&&item?.height?item.width/item.height:1));});const fitted=(grid.clientWidth-8*(row.length-1))/ratios.reduce((a,b)=>a+b,0),height=row.length<columns?Math.min(target*1.35,fitted):fitted;row.forEach((card,n)=>{card.style.width=Math.floor(row.length===columns&&height>target*1.1?Math.min(target,height*ratios[n]):height*ratios[n])+'px';card.style.setProperty('--image-height',Math.floor(height)+'px');});}}
